INSERT INTO workstreams (id, label, purpose) VALUES ('WS-CLIN', 'Clinical Workflow', 'Define how EndoScribe and PEPRisc fit into ERCP workflow, including prospective shadow-mode versus clinician-facing use.') ON CONFLICT (id) DO NOTHING;
INSERT INTO workstreams (id, label, purpose) VALUES ('WS-PLATFORM', 'EndoScribe Platform', 'Build the core transcription, structured note, variable extraction, logging, and dashboard platform.') ON CONFLICT (id) DO NOTHING;
INSERT INTO workstreams (id, label, purpose) VALUES ('WS-PEP', 'PEPRisc Integration', 'Integrate PEPRisc as the first clinical prediction module within EndoScribe.') ON CONFLICT (id) DO NOTHING;
INSERT INTO workstreams (id, label, purpose) VALUES ('WS-AUDIO', 'Audio Capture / Microphones', 'Compare phone microphones, OR-level microphones, and room setups for reliable endoscopy-suite audio capture.') ON CONFLICT (id) DO NOTHING;
INSERT INTO workstreams (id, label, purpose) VALUES ('WS-ASR', 'ASR / Transcription', 'Evaluate Whisper, Med-ASR-type systems, and other medical ASR options for ERCP speech.') ON CONFLICT (id) DO NOTHING;
INSERT INTO workstreams (id, label, purpose) VALUES ('WS-DIAR', 'Speaker Diarization', 'Isolate the primary endoscopist voice from multi-speaker room audio and cross-talk.') ON CONFLICT (id) DO NOTHING;
INSERT INTO workstreams (id, label, purpose) VALUES ('WS-DATA', 'Data Curation', 'Catalog existing recordings, select usable cases, link ground-truth notes, and prepare validation datasets.') ON CONFLICT (id) DO NOTHING;
INSERT INTO workstreams (id, label, purpose) VALUES ('WS-VALID', 'Validation Science', 'Quantify transcription accuracy, speaker attribution, variable extraction, PEPRisc agreement, latency, workflow feasibility, and safety.') ON CONFLICT (id) DO NOTHING;
INSERT INTO workstreams (id, label, purpose) VALUES ('WS-IRB', 'IRB / HIPAA / Hopkins IT', 'Ensure data capture, storage, processing, compute, and access comply with IRB, HIPAA, and Hopkins IT requirements.') ON CONFLICT (id) DO NOTHING;
INSERT INTO workstreams (id, label, purpose) VALUES ('WS-INFRA', 'Secure Infrastructure', 'Decide where ASR, diarization, structured extraction, and PEPRisc inference should run.') ON CONFLICT (id) DO NOTHING;
INSERT INTO workstreams (id, label, purpose) VALUES ('WS-FDA', 'FDA / Regulatory Strategy', 'Define intended use, CDS/SaMD classification, non-device CDS criteria, pre-submission needs, and AI lifecycle planning.') ON CONFLICT (id) DO NOTHING;
INSERT INTO workstreams (id, label, purpose) VALUES ('WS-TRANS', 'Industry / Translation', 'Prepare the project for JHTV, Olympus, licensing, and partnership discussions.') ON CONFLICT (id) DO NOTHING;
INSERT INTO workstreams (id, label, purpose) VALUES ('WS-FUTURE', 'Future Modules', 'Track downstream concepts such as template-generating agents, video mapping, papilla morphology, and additional prediction models.') ON CONFLICT (id) DO NOTHING;
