INSERT INTO risks (id, title, description, severity, mitigation, owner, status, related_task_ids) VALUES ('RISK-001', 'IRB amendment delays', 'IRB amendment process may delay prospective validation timeline', 'High', 'Start IRB assessment early; prepare amendment language in parallel', 'Richu Ravikumar', 'Open', '["IRB-001", "IRB-002"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO risks (id, title, description, severity, mitigation, owner, status, related_task_ids) VALUES ('RISK-002', 'ASR accuracy insufficient for medical terminology', 'General-purpose ASR may not achieve acceptable accuracy on ERCP-specific terminology', 'High', 'Evaluate multiple ASR systems; assess fine-tuning feasibility', 'Richu Ravikumar', 'Open', '["ASR-001", "ASR-002", "ASR-004"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO risks (id, title, description, severity, mitigation, owner, status, related_task_ids) VALUES ('RISK-003', 'Speaker diarization fails in noisy OR environment', 'Multi-speaker cross-talk and background noise may defeat diarization', 'Medium', 'Test in simulated conditions first; consider directional microphones', 'Richu Ravikumar', 'Open', '["DIAR-001", "DIAR-002", "AUDIO-001"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO risks (id, title, description, severity, mitigation, owner, status, related_task_ids) VALUES ('RISK-004', 'HIPAA-compliant compute access delays', 'Getting Hopkins-approved compute for ASR/PEPRisc may take longer than expected', 'Medium', 'Research options early; engage Hopkins IT proactively', 'Richu Ravikumar', 'Open', '["INFRA-001", "INFRA-002", "ASR-003"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO risks (id, title, description, severity, mitigation, owner, status, related_task_ids) VALUES ('RISK-005', 'Regulatory classification uncertainty', 'Uncertainty about FDA CDS/SaMD classification could affect project scope', 'High', 'Separate platform from prediction; maintain conservative intended-use statements', 'Richu Ravikumar', 'Open', '["FDA-003", "FDA-004"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO decisions (id, title, description, owner, status, related_task_ids) VALUES ('DEC-001', 'PEPRisc output audience during shadow validation', 'Should PEPRisc output be research-only, coordinator-facing, or clinician-facing?', 'PI', 'Pending', '["CLIN-002", "FDA-002"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO decisions (id, title, description, owner, status, related_task_ids) VALUES ('DEC-002', 'Compute environment for shadow validation', 'Where should ASR and PEPRisc inference run: local GPU, JHU Discovery, Hopkins server, or cloud?', 'Richu Ravikumar', 'Pending', '["INFRA-001", "INFRA-002"]'::jsonb) ON CONFLICT (id) DO NOTHING;
